import math

TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
TARGET_X, TARGET_Y = 30.0, 3.5
G1_X, G1_Y = 13.0, 2.0
G2_X, G2_Y = 23.0, 2.4

MAX_THRUST = 300.0  # Increased to overcome intense drag and momentum drain
LOW_THRUST = 100.0
HEAT_SAFE_FRAC = 0.75  # More conservative heat management

def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)

def build_agent(sandbox):
    # Craft is pre-initialized in environment; return None to avoid prohibited API
    return None

def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return

    pos = sandbox.get_craft_position()
    if pos is None:
        return

    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat
    step_idx = sandbox.get_step_count()

    # Early exit if already in target zone
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 0.0)
        return

    # Calculate thrust magnitude based on heat safety margin
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.25)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.35)

    # Adjust thrust in high-drag regions (Gate 1/2)
    if 12.0 <= x <= 14.0 or 22.0 <= x <= 24.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 2.0)  # Aggressive thrust boost in gate regions

    # Determine target waypoint with horizontal bias through gates
    wx, wy = _waypoint(x, y)

    # Adjust waypoint to ensure horizontal progress through gates
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if x > 24.0:
        wy = 4.0  # Ensure final approach is horizontal

    # Calculate direction vector to waypoint
    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx*dx + dy*dy)

    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 0.0)
        return

    # Normalize direction vector
    ux = dx / dist
    uy = dy / dist

    # Apply thrust in direction of waypoint
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Eliminate vertical assist to prevent upward drift
    # if y < 1.4:
    #     fy += min(5.0, (1.4 - y) * 2.5)  # Removed vertical assist

    # Apply wind compensation if in wind zone
    if 20.5 <= x <= 28.0:
        wind_fy = 10.0 * math.sin(0.055 * step_idx)  # Reduced wind amplitude
        fy -= wind_fy

    # Cap total thrust to prevent overexertion
    total = math.sqrt(fx*fx + fy*fy)
    cap = thrust_mag * 2.0  # Increased cap for high-thrust scenarios
    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    # Enforce minimum forward thrust through gates
    if G1_X - 1.0 <= x <= G1_X + 1.0:
        fx = max(fx, 250.0)  # Strong forward thrust through Gate 1
    if G2_X - 1.0 <= x <= G2_X + 1.0:
        fx = max(fx, 250.0)  # Strong forward thrust through Gate 2

    # Ensure forward progress by adjusting thrust direction if velocity is insufficient
    if x < 12.0:
        if fx < 150.0:
            fx = 150.0
    elif 12.0 <= x <= 14.0:
        if fx < 250.0:
            fx = 250.0
    elif 22.0 <= x <= 24.0:
        if fx < 250.0:
            fx = 250.0

    # Prevent upward drift by limiting vertical thrust when near gates
    if (G1_X - 1.0 <= x <= G1_X + 1.0 or G2_X - 1.0 <= x <= G2_X + 1.0) and y > 2.5:
        fy = min(fy, 0.0)  # No upward thrust near gates

    sandbox.apply_thrust(fx, fy)
